        function format_tanggal_indo($tanggal)
        {
            $bulan = [
                1 => 'Januari',
                'Februari',
                'Maret',
                'April',
                'Mei',
                'Juni',
                'Juli',
                'Agustus',
                'September',
                'Oktober',
                'November',
                'Desember'
            ];
            $tanggal = date('Y-m-d', strtotime($tanggal));
            $parts = explode('-', $tanggal);
            return $parts[2] . ' ' . $bulan[(int)$parts[1]] . ' ' . $parts[0];
        }
        ?>
        <p>Surabaya, <?= esc(format_tanggal_indo($tanggal)) ?></p>
